/**
 * Index maintenance on issue and comment writes.
 *
 * Owner C implements `@/server/services/search-service`.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("searchsvc", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

describe("services/search-service", () => {
  it("indexes an issue and a comment on creation", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Zulu index target" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Yankee index target",
      parentId: null,
      mentionedUserIds: [],
    });

    const issueHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Zulu",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(issueHits.total).toBe(1);
    expect(issueHits.items[0]).toMatchObject({ kind: "issue", id: issue.id });

    const commentHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Yankee",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(commentHits.total).toBe(1);
    expect(commentHits.items[0]).toMatchObject({ kind: "comment", id: comment.id });
  });

  it("re-indexes an updated issue in place", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Original Title Marker" }),
    );

    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "Updated Title Marker",
    });

    const stale = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Original Title Marker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(stale.total).toBe(0);

    const fresh = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Updated Title Marker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(fresh.total).toBe(1);
    expect(fresh.items[0]).toMatchObject({ id: issue.id });
  });

  it("drops an archived issue from the index", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ArchiveIndexMarker" }),
    );

    const before = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "ArchiveIndexMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(before.total).toBe(1);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const after = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "ArchiveIndexMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(after.total).toBe(0);
  });

  it("never returns another tenant's rows", async () => {
    const other = await createTenant("searchsvcother", "growth");
    await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "CrossTenantMarker" }),
    );

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "CrossTenantMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });

    expect(hits.total).toBe(0);
    expect(hits.items).toHaveLength(0);
  });

  it("falls back to plain matching when advanced_search is off", async () => {
    // The tenant is on "growth", which does not include advanced_search.
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "PlainMatchWorks" }),
    );

    await expect(
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "PlainMatchWorks",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).resolves.toMatchObject({ total: 1 });

    await expect(
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "status:PlainMatchWorks",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).rejects.toThrow(/not included in this plan/);
  });

  it("rate-limits search queries per organization", async () => {
    rateLimitState.allowed = false;

    await expect(
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "anything",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).rejects.toThrow(/rate limit/i);
  });
});
/**
 * Runs only for orgs whose digest hour has arrived and whose plan includes it.
 *
 * Owner C implements `@/server/jobs/digest-email-job`. The window arithmetic
 * itself is covered by `tests/lib/date.test.ts`.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as emailService from "@/server/services/email-service";
import * as featureFlagService from "@/server/services/feature-flag-service";
import { DIGEST_MAX_ENTRIES } from "@/config/constants";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { PlanId } from "@/types/billing";

let cleanup: () => void;

/** `2026-06-01T0{hour}:00:00.000Z` — every test gets its own hour so a scan
 * driven by one test's `now` never also matches another test's org. */
function nowAtHour(hour: number): Date {
  return new Date(Date.UTC(2026, 5, 1, hour, 0, 0, 0));
}

/** Creates a tenant on `plan` whose digest fires only at `digestHourUtc`, and
 * registers it with the usage rollup so `listOrgIdsForRollup` finds it. */
async function makeTenant(
  slug: string,
  digestHourUtc: number,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const tenant = await createTenant(slug, plan);
  await orgRepo.updateOrg(tenant.org.id, {
    orgId: tenant.org.id,
    settings: { digestHourUtc },
  });
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

/** Subscribes a member to the digest by setting one `digestOnly` preference. */
async function subscribeToDigest(tenant: Tenant): Promise<void> {
  await preferenceRepo.upsertPreference({
    orgId: tenant.org.id,
    userId: tenant.userIds.member,
    kind: "comment_created",
    inApp: false,
    email: false,
    digestOnly: true,
  });
}

async function insertNotificationAt(
  tenant: Tenant,
  at: Date,
  title: string,
): Promise<void> {
  vi.useFakeTimers();
  vi.setSystemTime(at);
  try {
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      kind: "comment_created",
      title,
      body: title,
      href: "/issues/1",
      actorId: null,
      channels: ["email"],
    });
  } finally {
    vi.useRealTimers();
  }
}

/** Pulls a `<td>key</td><td>value</td>` cell out of the generic email table. */
function cell(html: string, key: string): string | null {
  const match = html.match(new RegExp(`<td>${key}</td><td>([^<]*)</td>`));
  return match?.[1] ?? null;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("jobs/digest-email-job", () => {
  it("uses the org's configured digest hour to pick the window", async () => {
    const now = nowAtHour(1);
    const tenant = await makeTenant("digest-window", 1);
    await subscribeToDigest(tenant);

    await insertNotificationAt(tenant, new Date(now.getTime() - 12 * 3_600_000), "Recent update");
    await insertNotificationAt(tenant, new Date(now.getTime() - 30 * 3_600_000), "Stale update");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);

    expect(sendSpy).toHaveBeenCalledTimes(1);
    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
    expect(cell(html, "entryCount")).toBe("1");
    expect(cell(html, "headline")).toBe("Recent update");
  });

  it("skips an org whose digest hour has not arrived", async () => {
    const tenant = await makeTenant("digest-hour-not-yet", 2);
    await subscribeToDigest(tenant);
