/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexProjectTree, deleteSearchDocumentsForOrg
 */
import { createLogger } from "@/lib/logger";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { indexProjectTree } from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Rows read per page while walking the org's projects. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Rebuilds one tenant's index from scratch. Clears this org's entries, then
 * walks every page of its live projects and indexes each project's tree, so
 * the result holds exactly the documents the visibility rule allows. Archived
 * projects, and archived issues and comments, are never written back.
 *
 * Scoped to a single org on purpose: a full-fleet reindex is a sequence of
 * these, so one slow tenant cannot stall the rest.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteSearchDocumentsForOrg(orgId);

    let cursor: string | null = null;
    do {
      const page = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: false,
      });

      for (const project of page.items) {
        try {
          result.processed += await indexProjectTree(orgId, project);
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      cursor = page.nextCursor;
    } while (cursor !== null);
  });
}
EOF
